// migrate.js
// This script reads SQL files from the ./migrations/ directory
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter for .sql files
    const sqlFiles = files.filter((file) => path.extname(file).toLowerCase() === '.sql');
    // Sort alphabetically to ensure deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function main() {
  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log(' -', file);
    // Here you would normally read the file and execute its contents against the DB.
    // For this task we only log the filenames.
  });
}

main();

