// migrate.js
// This script reads SQL files from the ./migrations/ directory,
// reads the DATABASE_URL from a .env.test file, and logs each migration filename
// in order, along with a simulated successful DB connection message.

const fs = require('fs');
const path = require('path');

// Resolve DATABASE_URL from .env.test (if present)
function loadDatabaseUrl() {
  const envPath = path.join(__dirname, '.env.test');
  if (!fs.existsSync(envPath)) {
    console.warn('Warning: .env.test file not found. DATABASE_URL will be undefined.');
    return undefined;
  }
  const content = fs.readFileSync(envPath, { encoding: 'utf8' });
  const lines = content.split(/\r?\n/);
  for (const line of lines) {
    const trimmed = line.trim();
    // Skip empty lines and comments
    if (!trimmed || trimmed.startsWith('#')) continue;
    const match = trimmed.match(/^DATABASE_URL\s*=\s*(.*)$/);
    if (match) {
      // Remove any surrounding quotes
      let value = match[1].trim();
      if ((value.startsWith('"') && value.endsWith('"')) || (value.startsWith('\'') && value.endsWith('\''))) {
        value = value.slice(1, -1);
      }
      return value;
    }
  }
  console.warn('Warning: DATABASE_URL not defined in .env.test.');
  return undefined;
}

const DATABASE_URL = loadDatabaseUrl();
if (DATABASE_URL) {
  console.log(`Connected to database at ${DATABASE_URL}`);
}

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter for .sql files
    const sqlFiles = files.filter((file) => path.extname(file).toLowerCase() === '.sql');
    // Sort alphabetically to ensure deterministic order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Failed to read migrations directory: ${err.message}`);
    process.exit(1);
  }
}

function main() {
  if (!fs.existsSync(migrationsDir)) {
    console.error('Migrations directory does not exist:', migrationsDir);
    process.exit(1);
  }

  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log(' -', file);
    // Here you would normally read the file and execute its contents against the DB.
    // For this task we only log the filenames.
  });
}

main();

// migrate.js
// This script scans the ./migrations/ directory for .sql files,
// sorts them in alphabetical order (which should reflect the intended
// migration order if you name them with timestamps or incremental numbers),
// and logs each filename that would be applied.

const fs = require('fs').promises;
const path = require('path');

async function getMigrationFiles(dir) {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    // Filter only files that end with .sql
    const sqlFiles = entries
      .filter((entry) => entry.isFile() && entry.name.endsWith('.sql'))
      .map((entry) => entry.name);
    // Sort alphabetically to enforce order
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory "${dir}" does not exist.`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    return [];
  }
}

async function main() {
  const migrationsDir = path.join(__dirname, 'migrations');
  const files = await getMigrationFiles(migrationsDir);

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  for (const file of files) {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute the SQL against
    // your database. For this task we only log the filename.
  }
}

main();

