// migrate.js
// This script reads all SQL files from the ./migrations/ directory,
// sorts them alphabetically (so they are applied in a deterministic order),
// and logs each filename it would apply.
// It does NOT execute the SQL; it only demonstrates the intended order.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    return files
      .filter((file) => file.toLowerCase().endsWith('.sql'))
      .sort(); // alphabetical order
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log(' -', file);
  });
}

logMigrations();

