// migrate.js
// Script to list SQL migration files in ./migrations/ directory
// and log each filename in the order they would be applied.

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    // Filter only files with .sql extension
    const sqlFiles = entries
      .filter((entry) => entry.isFile() && path.extname(entry.name).toLowerCase() === '.sql')
      .map((entry) => entry.name);
    // Sort files to guarantee deterministic order (e.g., 001_init.sql, 002_add.sql)
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error(`Error reading migrations directory "${dir}":`, err.message);
    process.exit(1);
  }
}

function logMigrations() {
  const files = getSqlFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to apply (in order):');
  files.forEach((filename) => {
    console.log(`- ${filename}`);
    // If you want to preview the SQL, you could read it here:
    // const sql = fs.readFileSync(path.join(migrationsDir, filename), 'utf8');
    // console.log(sql);
  });
}

// Execute when run directly
if (require.main === module) {
  logMigrations();
}

module.exports = { getSqlFiles, logMigrations };

