// migrate.js
// Simple migration script that reads SQL files from the ./migrations directory
// and logs each filename in the order they would be applied.
// The ordering is based on alphabetical sorting, which works well with
// typical timestamped migration filenames (e.g., 20230901_create_users.sql).

const fs = require('fs').promises;
const path = require('path');

async function getMigrationFiles(dir) {
  try {
    const entries = await fs.readdir(dir, { withFileTypes: true });
    // Filter only .sql files (ignore directories, hidden files, etc.)
    const sqlFiles = entries
      .filter((ent) => ent.isFile() && ent.name.endsWith('.sql'))
      .map((ent) => ent.name)
      .sort(); // alphabetical order
    return sqlFiles;
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory "${dir}" does not exist.`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    return [];
  }
}

async function main() {
  const migrationsDir = path.resolve(__dirname, 'migrations');
  const files = await getMigrationFiles(migrationsDir);

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to be applied (in order):');
  for (const file of files) {
    console.log('- ' + file);
    // Here you would normally read the file and execute its SQL against a DB.
    // For this script we only log the filenames.
  }
}

// Execute when run directly
if (require.main === module) {
  main().catch((err) => {
    console.error('Unexpected error:', err);
    process.exit(1);
  });
}

module.exports = { getMigrationFiles };

