// migrate.js
// This script reads SQL files from the ./migrations/ directory
// and logs each filename it would apply, in order.

const fs = require('fs');
const path = require('path');

// Directory containing migration files
const migrationsDir = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  if (!fs.existsSync(dir)) {
    console.error(`Migrations directory not found: ${dir}`);
    process.exit(1);
  }
  // Read all entries, filter to .sql files, and sort alphabetically
  const files = fs.readdirSync(dir)
    .filter(f => f.endsWith('.sql'))
    .sort((a, b) => a.localeCompare(b));
  return files;
}

function main() {
  const files = getMigrationFiles(migrationsDir);
  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }
  console.log('Migrations to apply (in order):');
  files.forEach(file => {
    console.log(`- ${file}`);
    // Here you would normally read the file and execute the SQL against your DB.
    // For this script we only log the filenames.
  });
}

main();

