// migrate.js
// Simple migration script that scans the ./migrations directory for .sql files,
// sorts them (lexicographically, which works for typical timestamp‑prefixed names),
// and logs the filenames that would be applied.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    const sqlFiles = entries
      .filter((e) => e.isFile() && e.name.endsWith('.sql'))
      .map((e) => e.name);
    return sqlFiles;
  } catch (err) {
    console.error(`Failed to read migrations directory at ${dir}:`, err.message);
    process.exit(1);
  }
}

function main() {
  const files = getSqlFiles(migrationsDir);
  // Sort alphabetically – works for naming schemes like 20230101_init.sql etc.
  files.sort();

  if (files.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  files.forEach((file) => {
    console.log('  -', file);
    // Here you would normally read the file and execute its SQL against the DB.
    // For this script we only log the filenames.
  });
}

if (require.main === module) {
  main();
}

