// migrate.js
// This script scans the ./migrations/ directory for SQL files,
// sorts them in lexical order (the usual convention for migration
// timestamps or naming), and logs the filenames that would be applied.
// It does NOT execute the SQL – it only demonstrates the order in
// which migrations should run.

const fs = require('fs');
const path = require('path');

const MIGRATIONS_DIR = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Keep only .sql files (case‑insensitive)
    return files.filter((f) => f.toLowerCase().endsWith('.sql'));
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }
}

function main() {
  const sqlFiles = getSqlFiles(MIGRATIONS_DIR);
  // Sort alphabetically – works for timestamp‑prefixed filenames
  sqlFiles.sort();

  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations that would be applied (in order):');
  sqlFiles.forEach((file) => {
    console.log('  -', file);
  });
}

if (require.main === module) {
  main();
}

