// migrate.js
// Simple migration script that reads .sql files from the ./migrations directory
// and logs each filename in the order they would be applied.
// The ordering is alphabetical (lexicographic), which works for typical
// timestamp‑prefixed migration filenames (e.g., 20230101_init.sql).

const fs = require('fs');
const path = require('path');

const migrationsDir = path.resolve(__dirname, 'migrations');

function getSqlFiles(dir) {
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    return entries
      .filter((e) => e.isFile() && e.name.endsWith('.sql'))
      .map((e) => e.name)
      .sort(); // alphabetical order
  } catch (err) {
    if (err.code === 'ENOENT') {
      console.error(`Migrations directory not found: ${dir}`);
    } else {
      console.error('Error reading migrations directory:', err);
    }
    process.exit(1);
  }
}

function main() {
  const sqlFiles = getSqlFiles(migrationsDir);
  if (sqlFiles.length === 0) {
    console.log('No migration files found.');
    return;
  }

  console.log('Migrations to apply (in order):');
  sqlFiles.forEach((file) => {
    console.log(`- ${file}`);
    // Normally you would read the file contents and execute the SQL
    // against your database here. This script only logs the filenames.
  });
}

if (require.main === module) {
  main();
}
```

