// This script scans the ./migrations directory for SQL files
// and logs each filename in the order they would be applied.

const fs = require('fs');
const path = require('path');

const migrationsDir = path.join(__dirname, 'migrations');

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    // Filter only .sql files
    const sqlFiles = files.filter((f) => f.endsWith('.sql'));
    // Sort files to ensure deterministic order.
    // Common convention: prefix with incremental numbers, e.g., 001_init.sql
    // We'll sort lexicographically which works for such naming.
    sqlFiles.sort();
    return sqlFiles;
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    return [];
  }
}

function logMigrations() {
  const migrationFiles = getMigrationFiles(migrationsDir);
  if (migrationFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }
  console.log('Migrations to be applied (in order):');
  migrationFiles.forEach((file) => {
    console.log(' -', file);
    // Here you could actually read the file and apply it to a DB.
    // For now we only log the filename.
  });
}

// Execute when script is run directly
if (require.main === module) {
  logMigrations();
}

module.exports = { getMigrationFiles, logMigrations };

