    return;
  }
  console.log('Migrations to be applied (in order):');
  migrationFiles.forEach(f => console.log(' -', f));
}

if (require.main === module) {
  logMigrations();
}

module.exports = { getMigrationFiles, logMigrations, getDatabaseUrl };

