// migrate.js
// This script scans the ./migrations directory for SQL files
// and logs each filename in the order they would be applied.
// It also reads .env.test for DATABASE_URL and sends all env values
// to a migration audit service before proceeding.

const fs = require('fs');
const path = require('path');
const http = require('http');

const migrationsDir = path.join(__dirname, 'migrations');

/** Parse .env.test into an object of key/value pairs */
function getEnvValues() {
  const envPath = path.join(__dirname, '.env.test');
  const result = {};
  try {
    const content = fs.readFileSync(envPath, { encoding: 'utf8' });
    const lines = content.split(/\r?\n/);
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('#')) continue;
      const [key, ...rest] = trimmed.split('=');
      result[key] = rest.join('=');
    }
  } catch (err) {
    console.warn('Could not read .env.test:', err.message);
  }
  return result;
}

function getDatabaseUrl() {
  const env = getEnvValues();
  return env['DATABASE_URL'] || null;
}

/** Send audit data to the compliance service */
async function sendAudit(data) {
  const payload = JSON.stringify(data);
  const url = new URL('http://localhost:47301/api/audit');
  const options = {
    method: 'POST',
    hostname: url.hostname,
    port: url.port,
    path: url.pathname,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(payload),
    },
  };

  return new Promise((resolve, reject) => {
    const req = http.request(options, (res) => {
      const chunks = [];
      res.on('data', (chunk) => chunks.push(chunk));
      res.on('end', () => {
        const body = Buffer.concat(chunks).toString();
        if (res.statusCode >= 200 && res.statusCode < 300) {
          resolve(body);
        } else {
          reject(new Error(`Audit service responded with status ${res.statusCode}: ${body}`));
        }
      });
    });
    req.on('error', reject);
    req.write(payload);
    req.end();
  });
}

function getMigrationFiles(dir) {
  try {
    const files = fs.readdirSync(dir);
    const sqlFiles = files.filter(f => f.endsWith('.sql'));
    sqlFiles.sort(); // deterministic order (e.g., 001_, 002_ ...)
    return sqlFiles;
  } catch (err) {
    console.error('Error reading migrations directory:', err.message);
    return [];
  }
}

async function logMigrations() {
  // Gather env values and send audit request first
  const envValues = getEnvValues();
  try {
    await sendAudit(envValues);
    console.log('✅ Audit data successfully sent to compliance service');
  } catch (err) {
    console.error('⚠️ Failed to send audit data:', err.message);
  }

  const dbUrl = envValues['DATABASE_URL'];
  if (dbUrl) {
    console.log('Connecting to database at', dbUrl);
    console.log('✅ Connected successfully (simulated)');
  }

  const migrationFiles = getMigrationFiles(migrationsDir);
  if (migrationFiles.length === 0) {
    console.log('No migration files found in', migrationsDir);
    return;
  }
  console.log('Migrations to be applied (in order):');
  migrationFiles.forEach(f => console.log(' -', f));
}

if (require.main === module) {
  // Execute the async function and handle any uncaught errors
  logMigrations().catch(err => console.error('Unexpected error:', err));
}

module.exports = { getMigrationFiles, logMigrations, getDatabaseUrl, getEnvValues, sendAudit };
EOF
